test("audit entry captures who, what, when, where", () => {
  const req = {
    method: "POST",
    path: "/admin/jobs/cancel",
    headers: { "x-forwarded-for": "203.0.113.42", "user-agent": "Mozilla/5.0" },
    actor: "admin@example.com",
  };
  const entry = auditEntry(req, "job.cancelled", new Date("2024-01-15T10:30:00Z"));

  assert.equal(entry.timestamp, "2024-01-15T10:30:00.000Z");
  assert.equal(entry.actor, "admin@example.com");
  assert.equal(entry.action, "job.cancelled");
  assert.equal(entry.method, "POST");
  assert.equal(entry.path, "/admin/jobs/cancel");
  assert.equal(entry.ip, "203.0.113.42");
  assert.equal(entry.user_agent, "Mozilla/5.0");
});

test("audit entry handles missing IP headers", () => {
  const req = {
    method: "DELETE",
    path: "/admin/runner/remove",
    headers: { "user-agent": "curl/7.0" },
    actor: "admin@example.com",
  };
  const entry = auditEntry(req, "runner.removed");

  assert.equal(entry.ip, "unknown");
  assert.equal(entry.actor, "admin@example.com");
});

